import { cn } from "@/lib/utils"; // Assuming cn utility is available
import { ArrowRight } from "lucide-react";
import React from "react";
import { FadeIn } from "./FadeIn";

export const BuildAISection: React.FC = () => {
  const [step, setStep] = React.useState<
    "idle" | "typing-user" | "thinking" | "typing-ai" | "completed"
  >("idle");
  const [userText, setUserText] = React.useState("");
  const [aiText, setAiText] = React.useState("");

  const userFullText = "Why is human feedback essential for LLMs?";
  const aiFullText =
    "RLHF (Reinforcement Learning from Human Feedback) aligns models with human intent, ensuring they are helpful, harmless, and honest.";

  React.useEffect(() => {
    let isMounted = true;

    const runSimulation = async () => {
      while (isMounted) {
        // Reset state
        if (!isMounted) break;
        setStep("typing-user");
        setUserText("");
        setAiText("");

        // Simulate User Typing (slower, variable speed)
        for (let i = 0; i <= userFullText.length; i++) {
          if (!isMounted) break;
          setUserText(userFullText.slice(0, i));
          await new Promise((r) => setTimeout(r, 50 + Math.random() * 30));
        }

        if (!isMounted) break;

        // Thinking Phase
        setStep("thinking");
        await new Promise((r) => setTimeout(r, 1200));

        if (!isMounted) break;

        // Simulate AI Streaming (faster, consistent)
        setStep("typing-ai");
        for (let i = 0; i <= aiFullText.length; i++) {
          if (!isMounted) break;
          setAiText(aiFullText.slice(0, i));
          await new Promise((r) => setTimeout(r, 15)); // Fast streaming
        }

        if (!isMounted) break;
        setStep("completed");

        // Pause before restarting the loop
        await new Promise((r) => setTimeout(r, 4000));
      }
    };

    runSimulation();

    return () => {
      isMounted = false;
    };
  }, []);

  return (
    <section className="py-24 bg-rockship-950 text-white border-t border-white/5">
      <div className="container mx-auto px-6">
        <FadeIn className="text-center mb-20">
          <h2 className="text-rockship-accent font-semibold tracking-widest uppercase text-sm mb-4">
            Build AI
          </h2>
          <h3 className="text-4xl md:text-5xl font-display font-medium text-white mb-6">
            Powering Frontier AI
          </h3>
          <p className="text-lg text-rockship-300 leading-relaxed">
            Next Generation AI powered by world-class data.
          </p>
        </FadeIn>

        <FadeIn>
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-16 items-center">
            {/* Left: Chat UI Mockup */}
            <div className="w-full relative group">
              {/* Glow Effect */}
              <div className="absolute -inset-1 bg-gradient-to-r from-purple-500/20 to-blue-500/20 rounded-2xl blur-lg opacity-50 group-hover:opacity-100 transition duration-1000"></div>

              <div className="relative bg-[#050505] border border-white/10 rounded-xl overflow-hidden shadow-2xl aspect-[4/3] flex flex-col">
                {/* Window Controls */}
                <div className="flex items-center justify-between px-6 py-4 border-b border-white/5 bg-white/[0.02]">
                  <div className="flex gap-2">
                    <div className="w-3 h-3 rounded-full bg-[#FF5F57]" />
                    <div className="w-3 h-3 rounded-full bg-[#FEBC2E]" />
                    <div className="w-3 h-3 rounded-full bg-[#28C840]" />
                  </div>
                  <div className="text-xs font-mono text-gray-500">
                    AI Text Generator
                  </div>
                  <div className="w-12" /> {/* Spacer */}
                </div>

                {/* Chat Area */}
                <div className="flex-1 p-6 relative font-sans flex flex-col gap-6 overflow-hidden">
                  {/* Corrected Layout: User Right, AI Left */}
                  <div
                    className={cn(
                      "flex items-end gap-3 justify-end transition-opacity duration-500",
                      step === "idle" ? "opacity-0" : "opacity-100"
                    )}
                  >
                    <div className="bg-[#1A1A1A] border border-white/10 rounded-2xl rounded-br-sm py-3 px-5 text-sm text-gray-200 max-w-[85%] text-left">
                      {userText}
                      {step === "typing-user" && (
                        <span className="w-1.5 h-4 bg-rockship-accent inline-block align-middle ml-1 animate-pulse" />
                      )}
                    </div>
                    <div className="w-8 h-8 rounded-full bg-gradient-to-br from-gray-700 to-gray-600 overflow-hidden shrink-0 border border-white/10">
                      <img
                        src="https://picsum.photos/seed/user/100/100"
                        className="w-full h-full object-cover opacity-80"
                        alt="User"
                      />
                    </div>
                  </div>

                  {/* AI Response */}
                  {(step === "thinking" ||
                    step === "typing-ai" ||
                    step === "completed") && (
                    <div className="flex items-end gap-3 justify-start animate-in fade-in slide-in-from-bottom-2 duration-500">
                      <div className="w-8 h-8 rounded-full bg-rockship-accent/20 flex items-center justify-center shrink-0 border border-rockship-accent/30">
                        <div className="w-4 h-4 rounded-sm bg-rockship-accent" />
                      </div>
                      <div className="bg-rockship-900/80 border border-rockship-accent/20 rounded-2xl rounded-bl-sm py-3 px-5 text-sm text-gray-300 max-w-[85%]">
                        {step === "thinking" ? (
                          <div className="flex gap-1 h-5 items-center">
                            <span className="w-1.5 h-1.5 bg-gray-500 rounded-full animate-bounce [animation-delay:-0.3s]" />
                            <span className="w-1.5 h-1.5 bg-gray-500 rounded-full animate-bounce [animation-delay:-0.15s]" />
                            <span className="w-1.5 h-1.5 bg-gray-500 rounded-full animate-bounce" />
                          </div>
                        ) : (
                          <span>
                            {aiText}
                            {step === "typing-ai" && (
                              <span className="w-1.5 h-4 bg-rockship-accent inline-block align-middle ml-1 animate-pulse" />
                            )}
                          </span>
                        )}
                      </div>
                    </div>
                  )}
                </div>
              </div>
            </div>

            {/* Right: Content */}
            <div className="space-y-8">
              <h3 className="text-3xl md:text-5xl font-display font-normal">
                Generative AI
              </h3>
              <p className="text-gray-500 font-medium text-lg">
                Powering the next generation of Generative AI
              </p>
              <p className="text-gray-400 leading-relaxed max-w-lg">
                Rockship Generative AI Data Engine powers many of the most
                advanced LLMs and generative models in the world through
                world-class RLHF, data generation, model evaluation, safety, and
                alignment.
              </p>
              <div className="flex flex-wrap items-center gap-6 pt-4">
                <button className="px-8 py-3 bg-white text-black font-bold rounded-lg hover:bg-gray-200 transition-all hover:scale-105 active:scale-95 duration-200 flex items-center gap-2">
                  Book a Demo <ArrowRight size={16} />
                </button>
                <button className="group px-4 py-3 text-white font-bold rounded-lg hover:text-rockship-accent transition-colors flex items-center gap-2">
                  Build AI{" "}
                  <span className="group-hover:translate-x-1 transition-transform">
                    &rarr;
                  </span>
                </button>
              </div>
            </div>
          </div>
        </FadeIn>
      </div>
    </section>
  );
};
